const fs = require('fs');

function main() {
    const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/).map(Number);
    if (input.length < 6) return;

    const totalWeight = input.reduce((acc, val) => acc + val, 0);

    if (totalWeight % 3 !== 0) {
        console.log('N');
        return;
    }

    const target = totalWeight / 3;

    // O terceiro andar tem exatamente 1 cubo, que deve ter peso igual a target
    // Os outros dois andares têm 2 cubos e 3 cubos, ambos somando target.
    let possible = false;

    for (let i = 0; i < 6; i++) {
        if (input[i] === target) {
            // O cubo i fica no terceiro andar.
            // Agora verificamos se entre os outros 5 cubos, existe um par que soma target.
            const remaining = [];
            for (let j = 0; j < 6; j++) {
                if (j !== i) remaining.push(input[j]);
            }

            for (let a = 0; a < remaining.length; a++) {
                for (let b = a + 1; b < remaining.length; b++) {
                    if (remaining[a] + remaining[b] === target) {
                        possible = true;
                        break;
                    }
                }
                if (possible) break;
            }
        }
        if (possible) break;
    }

    console.log(possible ? 'S' : 'N');
}

main();
